using UnityEngine;

public class Spinner : MonoBehaviour
{
    // How fast the cube turns, in degrees per second.
    public float speed = 90f;

    // True means spin, false means stay still.
    public bool isSpinning = true;

    // The text that Start writes to the Console.
    public string message = "Spinner started on ";

    // Start runs once, the moment Play begins.
    void Start()
    {
        Debug.Log(message + gameObject.name);
    }

    // Update runs once every frame while Play is on.
    void Update()
    {
        if (isSpinning)
        {
            transform.Rotate(0f, speed * Time.deltaTime, 0f);
        }
    }
}

using UnityEngine;
using UnityEngine.InputSystem;

public class PlayerController : MonoBehaviour
{
    // How hard the keys push the ball. You can change it in the Inspector.
    public float speed = 10f;

    // The direction the player is asking for right now.
    private Vector3 moveInput;

    void Update()
    {
        // Start every frame with no input.
        moveInput = Vector3.zero;

        // Keyboard.current is empty (null) if no keyboard is connected.
        Keyboard keyboard = Keyboard.current;
        if (keyboard == null)
        {
            return;
        }

        // x is left and right. z is forward and back.
        float x = 0f;
        float z = 0f;

        if (keyboard.aKey.isPressed) { x = x - 1f; }
        if (keyboard.dKey.isPressed) { x = x + 1f; }
        if (keyboard.sKey.isPressed) { z = z - 1f; }
        if (keyboard.wKey.isPressed) { z = z + 1f; }

        // Make the direction exactly length 1, so diagonals are not faster.
        moveInput = new Vector3(x, 0f, z).normalized;

        // Temporary: show the direction in the Console.
        if (moveInput != Vector3.zero) { Debug.Log("Move input: " + moveInput); }
    }
}

using UnityEngine;
using UnityEngine.InputSystem;

public class PlayerController : MonoBehaviour
{
    // How hard the keys push the ball. You can change it in the Inspector.
    public float speed = 10f;

    // The direction the player is asking for right now.
    private Vector3 moveInput;

    // The ball's Rigidbody, found once when Play begins.
    private Rigidbody rb;

    void Start()
    {
        rb = GetComponent<Rigidbody>();
    }

    void Update()
    {
        // Start every frame with no input.
        moveInput = Vector3.zero;

        Keyboard keyboard = Keyboard.current;
        if (keyboard == null)
        {
            return;
        }

        // x is left and right. z is forward and back.
        float x = 0f;
        float z = 0f;

        if (keyboard.aKey.isPressed) { x = x - 1f; }
        if (keyboard.dKey.isPressed) { x = x + 1f; }
        if (keyboard.sKey.isPressed) { z = z - 1f; }
        if (keyboard.wKey.isPressed) { z = z + 1f; }

        // Make the direction exactly length 1, so diagonals are not faster.
        moveInput = new Vector3(x, 0f, z).normalized;
    }

    // FixedUpdate runs on the physics clock, so forces go here.
    void FixedUpdate()
    {
        // Push the ball in the direction the player asked for.
        rb.AddForce(moveInput * speed);
    }
}

using UnityEngine;
using UnityEngine.InputSystem;

public class PlayerController : MonoBehaviour
{
    // How hard the keys push the ball. You can change it in the Inspector.
    public float speed = 10f;

    // The Move input as two numbers: x is left and right, y is forward and back.
    private Vector2 moveInput;

    // The ball's Rigidbody and the project's Move action, found once in Start.
    private Rigidbody rb;
    private InputAction moveAction;

    void Start()
    {
        rb = GetComponent<Rigidbody>();
        moveAction = InputSystem.actions.FindAction("Move");
    }

    void Update()
    {
        // Read the Move action once per frame.
        moveInput = moveAction.ReadValue<Vector2>();
    }

    void FixedUpdate()
    {
        // Turn the two numbers into a flat 3D direction: no up or down.
        Vector3 direction = new Vector3(moveInput.x, 0f, moveInput.y);

        // Push the ball.
        rb.AddForce(direction * speed);
    }
}

using UnityEngine;

public class CameraFollow : MonoBehaviour
{
    // The object to follow. You drag Player into this slot in the Inspector.
    public Transform target;

    // How far the camera sits from the target, worked out once in Start.
    private Vector3 offset;

    void Start()
    {
        // The gap between the target and the camera, taken from where you placed the camera.
        offset = transform.position - target.position;
    }

    // LateUpdate runs after all the Update methods in the frame, so the target has already moved.
    void LateUpdate()
    {
        // Put the camera at the target's position plus the gap.
        transform.position = target.position + offset;
    }
}

