        // other is the object we just touched
        Debug.Log("Picked up " + other.name);
        Destroy(other.gameObject);
    }
}

using UnityEngine;

public class PickupCollector : MonoBehaviour
{
    // How many pickups there are in the arena
    [SerializeField] private int totalPickups = 8;

    // The score: how many pickups we have collected so far
    private int score = 0;

    void OnTriggerEnter(Collider other)
    {
        // Only do something if the thing we touched is tagged Pickup
        if (other.CompareTag("Pickup"))
        {
            Destroy(other.gameObject);
            score = score + 1;
            Debug.Log("Score: " + score + " / " + totalPickups);

            // Have we collected them all?
            if (score >= totalPickups)
            {
                Debug.Log("You win!");
            }
        }
    }
}

