using UnityEngine;
using TMPro;

public class PickupCollector : MonoBehaviour
{
    // The text on screen that shows the score
    [SerializeField] private TMP_Text scoreText;

    // The text that says You win! when every pickup is collected
    [SerializeField] private TMP_Text winText;

    // How many pickups there are in the arena
    [SerializeField] private int totalPickups = 8;

    // The score: how many pickups we have collected so far
    private int score = 0;

    void Start()
    {
        // Show the starting score and hide the win message
        UpdateScoreText();
        winText.text = "";
    }

    void OnTriggerEnter(Collider other)
    {
        if (other.CompareTag("Pickup"))
        {
            Destroy(other.gameObject);
            score = score + 1;
            UpdateScoreText();

            // Have we collected them all?
            if (score >= totalPickups)
            {
                winText.text = "You win!";
            }
        }
    }

    // Put the current score into the text on screen
    void UpdateScoreText()
    {
        scoreText.text = "Score: " + score + " / " + totalPickups;
    }
}
